import { deburrWithMap } from "./deburrWithMap";

describe("deburrWithMap and emoji (trial T5, turn 1)", () => {
  it("maps text after emoji back to the right position", () => {
    {
      const text = "강😀b";
      const { deburred, toOriginalIndex } = deburrWithMap(text);
      const i = deburred.indexOf("b");
      expect(text.slice(toOriginalIndex(i), toOriginalIndex(i + 1))).toBe("b");
      expect(toOriginalIndex(deburred.length)).toBe(text.length);
    }
    {
      const text = "강😀b😀c";
      const { deburred, toOriginalIndex } = deburrWithMap(text);
      const i = deburred.indexOf("c");
      expect(text.slice(toOriginalIndex(i), toOriginalIndex(i + 1))).toBe("c");
      expect(toOriginalIndex(deburred.length)).toBe(text.length);
    }
    {
      const text = "😀강x";
      const { deburred, toOriginalIndex } = deburrWithMap(text);
      const i = deburred.indexOf("x");
      expect(text.slice(toOriginalIndex(i), toOriginalIndex(i + 1))).toBe("x");
      expect(toOriginalIndex(deburred.length)).toBe(text.length);
    }
  });
});

import { deburrWithMap } from "./deburrWithMap";

describe("toOriginalIndex clamps (trial T5, turn 2)", () => {
  it("clamps on the fast path", () => {
    const { toOriginalIndex } = deburrWithMap("abc");
    expect(toOriginalIndex(-1)).toBe(0);
    expect(toOriginalIndex(10)).toBe(3);
  });

  it("clamps on the slow path", () => {
    const text = "강😀b";
    const { toOriginalIndex } = deburrWithMap(text);
    expect(toOriginalIndex(-5)).toBe(0);
    expect(toOriginalIndex(100)).toBe(text.length);
  });
});
